"use client"

import { useFieldControl } from "@ui-sdk/react/field"
import { createParts } from "@ui-sdk/react/primitive"
import type { ComponentProps, ReactNode } from "react"

import { floatingLabelControls } from "@/components/ui/field"
import { fieldSurfaceClassName } from "@/components/ui/input"
import { nativeSelect, type NativeSelectItem, type NativeSelectOptions } from "@/components/ui/native-select-primitive"
import { cn } from "@/lib/utils"

const { Root: NativeSelectRoot } = createParts(nativeSelect, { root: "select" })

type NativeSelectOption = { value: string; label: string; disabled?: boolean; description?: ReactNode }
type NativeSelectOptionGroup = { label: string; options: NativeSelectOption[] }
type NativeSelectOptionList = (NativeSelectOption | NativeSelectOptionGroup)[]

type NativeSelectProps = Omit<
  ComponentProps<"select">,
  "value" | "defaultValue" | "onChange" | "children" | "multiple"
> &
  Pick<NativeSelectOptions, "value" | "defaultValue" | "onValueChange"> & {
    /** The same shape as Select's `options`; a description has no place in a native list and is left out. */
    options: NativeSelectOptionList
    /** Shows while nothing is chosen; it can't be chosen again once something is, unless `clearable` is set. */
    placeholder?: string
    /** The label of a first choice that sets the value to `null`, like "No team". */
    clearable?: string
  }

const isGroup = (option: NativeSelectOption | NativeSelectOptionGroup): option is NativeSelectOptionGroup =>
  "options" in option

function agentItems(options: NativeSelectOptionList, clearable?: string): NativeSelectItem[] {
  const items = options.flatMap((option) => (isGroup(option) ? option.options : [option]))
  return [
    ...(clearable === undefined ? [] : [{ value: "", label: clearable }]),
    ...items.filter((item) => !item.disabled).map(({ value, label }) => ({ value, label })),
  ]
}

function renderOption(option: NativeSelectOption) {
  return (
    <option key={option.value} value={option.value} disabled={option.disabled}>
      {option.label}
    </option>
  )
}

/** A styled native `<select>`: the platform's own picker, best on touch screens. Agents set it by label. */
function NativeSelect({
  options,
  placeholder,
  clearable,
  value,
  defaultValue,
  onValueChange,
  className,
  disabled,
  ...props
}: NativeSelectProps) {
  const field = useFieldControl()
  const own = {
    ...props,
    name: props.name ?? field?.name,
    disabled: disabled ?? field?.disabled,
    "data-slot": "native-select",
    className: cn(
      fieldSurfaceClassName,
      // oxlint-disable-next-line eskais/spacing-tokens -- the end padding clears the chevron drawn over the select
      "h-field-control w-full min-w-0 cursor-pointer appearance-none rounded-control ps-control-x pe-9 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50",
      className,
    ),
  }
  const merged = field ? (field.props(own) as typeof own) : own
  return (
    <div data-slot="native-select-wrapper" className="relative w-full min-w-0">
      <NativeSelectRoot
        {...merged}
        items={agentItems(options, clearable)}
        value={value}
        defaultValue={defaultValue}
        onValueChange={onValueChange}
      >
        {clearable === undefined ? (
          <option value="" disabled={placeholder !== undefined} hidden={placeholder === undefined}>
            {placeholder}
          </option>
        ) : (
          <option value="">{clearable}</option>
        )}
        {options.map((option) =>
          isGroup(option) ? (
            <optgroup key={`group:${option.label}`} label={option.label}>
              {option.options.map(renderOption)}
            </optgroup>
          ) : (
            renderOption(option)
          ),
        )}
      </NativeSelectRoot>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-y-0 end-control-x flex items-center text-muted-foreground [&>svg]:size-4"
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="m6 9 6 6 6-6" />
        </svg>
      </span>
    </div>
  )
}

floatingLabelControls.add(NativeSelect)

export { NativeSelect }
export type { NativeSelectOption, NativeSelectOptionGroup, NativeSelectOptionList, NativeSelectProps }

import { createChange, definePrimitive, type ChangeDetails } from "@ui-sdk/core"

type NativeSelectChangeReason = "input-change" | "imperative"

type NativeSelectItem = { value: string; label: string }

type NativeSelectOptions = {
  /** Every choice, flat, for agents: the empty value is the placeholder or the clearable choice. */
  items?: NativeSelectItem[]
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string | null, details: ChangeDetails<NativeSelectChangeReason>) => void
}

// UI SDK ships no part for a native <select>, and agents see only UI SDK parts, so this one reports its value and
// choices to them and takes `setValue` like a Select does.
const nativeSelect = definePrimitive({
  name: "native-select",
  options: { items: "value", value: "value", defaultValue: "value", onValueChange: "callback" },
  controlled: ["value"],
  state: (options: NativeSelectOptions) => ({
    value: options.value ?? options.defaultValue ?? null,
    items: options.items ?? [],
  }),
  sync: (options) => ({ items: options.items ?? [], ...(options.value === undefined ? {} : { value: options.value }) }),
  api: (context) => {
    const change = createChange(context)
    return {
      // The agent bridge passes arguments unchecked; an unknown value is refused with the real ones by `closed`.
      setValue(value: unknown, event?: Event) {
        const next = value === "" || value === null || value === undefined ? null : String(value)
        return change("value", next, { reason: event ? "input-change" : "imperative", event })
      },
    }
  },
  slots: (slot) => ({
    root: slot({
      on: {
        change: (event, { api, el, store }) => {
          api.setValue((event.target as HTMLSelectElement).value, event)
          // A refused or still-controlled change leaves the element showing the old value until state says otherwise.
          queueMicrotask(() => {
            const select = el as HTMLSelectElement
            const value = store.get().value ?? ""
            if (select.value !== value) select.value = value
          })
        },
      },
      bind: (el, part) => {
        const select = el as HTMLSelectElement
        const show = () => {
          const value = part.store.get().value ?? ""
          if (select.value !== value) select.value = value
        }
        show()
        return part.store.subscribe(show)
      },
    }),
  }),
  agent: { actions: ["setValue"], closed: true },
})

export { nativeSelect }
export type { NativeSelectChangeReason, NativeSelectItem, NativeSelectOptions }
